function getSelectedLegendYAxisBounds(
  series: Series[],
  legend?: LineChartProps['legend']
) {
  if (!series[1]) {
    return null;
  }
  let minSeries = series[0];
  let maxSeries: Series | undefined;
  series.forEach((s, idx) => {
    if (legend?.selected?.[s.seriesName] !== false) {
      minSeries = series[idx];
      maxSeries ??= series[idx];
    }
  });
  const max = Math.max(...(maxSeries?.data.map(({value}) => value as number) ?? []));
  const min = Math.min(
    ...(minSeries?.data.map(({value}) => value as number) ?? []).filter(value => !!value)
  );
  return {max, min};
}

